/* eslint-disable space-in-parens */

/// <reference types="@stdlib/types"/>

import zeros = require( '@stdlib/ndarray/zeros' );
import zeroTo = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	zeroTo( x ); // $ExpectType float64ndarray
	zeroTo( x, {} ); // $ExpectType float64ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	zeroTo( '5' ); // $ExpectError
	zeroTo( 5 ); // $ExpectError
	zeroTo( true ); // $ExpectError
	zeroTo( false ); // $ExpectError
	zeroTo( null ); // $ExpectError
	zeroTo( void 0 ); // $ExpectError
	zeroTo( {} ); // $ExpectError
	zeroTo( ( x: number ): number => x ); // $ExpectError

	zeroTo( '5', {} ); // $ExpectError
	zeroTo( 5, {} ); // $ExpectError
	zeroTo( true, {} ); // $ExpectError
	zeroTo( false, {} ); // $ExpectError
	zeroTo( null, {} ); // $ExpectError
	zeroTo( void 0, {} ); // $ExpectError
	zeroTo( {}, {} ); // $ExpectError
	zeroTo( ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	zeroTo( x, '5' ); // $ExpectError
	zeroTo( x, 5 ); // $ExpectError
	zeroTo( x, true ); // $ExpectError
	zeroTo( x, false ); // $ExpectError
	zeroTo( x, null ); // $ExpectError
	zeroTo( x, [] ); // $ExpectError
	zeroTo( x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid `dims` option...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	zeroTo( x, { 'dims': '5' } ); // $ExpectError
	zeroTo( x, { 'dims': 5 } ); // $ExpectError
	zeroTo( x, { 'dims': true } ); // $ExpectError
	zeroTo( x, { 'dims': false } ); // $ExpectError
	zeroTo( x, { 'dims': null } ); // $ExpectError
	zeroTo( x, { 'dims': {} } ); // $ExpectError
	zeroTo( x, { 'dims': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	zeroTo(); // $ExpectError
	zeroTo( x, {}, {} ); // $ExpectError
}
